INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (48,'zhTW','打嗝!哈哈!你想再來一次嗎？$B$B在南方那片藤蔓蜿蜒纏繞的土地上$B藏著一口深不見底的水井$B純淨如聖光的聖潔之女$B現在就把神聖的泉水帶來給我。',0);
