INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8103,'zhTW','哈卡莉部族都畏懼你，$n。他們談論著本以為只有他們那位無面之神才能造成的恐怖。你已經用卡加羅的力量將他們燒灼殆盡。如今他們對兩個地方都心生恐懼。$b$b是時候進一步強化這顆卵石了。把護符交給我。',0);
DELETE FROM `quest_request_items_locale` WHERE `ID` = 8107 AND `locale` = 'zhTW';
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8107,'zhTW','贊達拉巨魔之間，榮譽是要靠贏得的，$n。有了榮譽，就會有回報——友誼、結盟……$b$b把護符交給我，讓我來強化它的力量。',0);
