INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8108,'zhTW','我已經準備好了，$c。我會再次強化你的護符。我只要求你繼續消滅哈卡爾和他的爪牙。$b$b把護符給我。',0);
