INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8111,'zhTW','嘿，夥計!很高興再見到你。整個部族都在談論你殺死哈卡莉部族的事蹟。莫索爾要我在你的護符裡再加點魔力。把它交出來，梅維琪會讓它變得更好。',0);
