INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8112,'zhTW','護符怎麼樣了，夥計？看來是時候在它的葉片上再加點魔法和魔力了。它需要在凋零之處重新綻放。把它交出來，梅維琪會把它修好的。',0);
