INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8142,'zhTW','了不起，$n。你有種殺戮的天賦，我已經很多年沒在別人身上感受過了。就連莫索爾也注意到了你為贊達拉部族所做的一切。是時候再次強化你的護符了。把它給我。',0);
