INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8143,'zhTW','我能感覺到你已經對哈卡莉部族造成了無數的死傷，$n。你身上帶著他們魔力的臭味。$b$b我猜暗影護符在這場屠殺中幫上了忙？把它給我，讓我強化它的力量。',0);
