INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8146,'zhTW','即使在這裡，我也能聽見你的箭雨摧毀我們敵人的聲音。他們痛苦的哀嚎迴盪不已。$b$b你已經在贊達拉的巨魔之間闖出了名號，$n。我們對你所做的一切心懷感激。$b$b把你的護符交給我，讓我再為它編織一層力量。',0);
DELETE FROM `quest_request_items_locale` WHERE `ID` = 8147 AND `locale` = 'zhTW';
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8147,'zhTW','啊，$n，能再次聞到你的氣味真好。$b$b<法爾希爾露齒一笑。>$b$b你得多包涵我的幽默感。它有時候相當惡趣味。$b$b我能感覺到你已經給我們的敵人帶來了極大的痛苦。哈卡爾的部隊憤怒地喊著你的名字。這真是太好了。$b$b你已經為你的護符贏得了另一層編織。把它交給我。',0);
